 if(kind==='decision'){const d={...r,horizon:v.horizon,invalidation:v.invalidation,symbol:v.symbol.toUpperCase(),assumptions:v.assumptions,evidence:v.evidence,id:r?.id||id(),title:v.title,date:v.date,reviewDate:v.reviewDate,rationale:v.rationale,expected:v.expected,thesisId:v.thesisId,portfolioId:v.portfolioId,reports:f.getAll('reports'),status:r?.status||'Open',outcome:r?.outcome||''};if(!r&&seed){if(seed.context)d.researchContext=structuredClone(seed.context);if(seed.analysisRefs)d.analysisRefs=structuredClone(seed.analysisRefs);}savedId=d.id;retainEntryHistory(d,r);if(r)next.decisions[next.decisions.findIndex(d=>d.id===r.id)]=d;else next.decisions.push(d);dest='decisions';}
 if(kind==='flowless'){if(!flowlessCandidate||flowlessCandidate.requestedSymbol!==v.symbol||flowlessCandidate.requestedAsOf!==v.asOf)throw Error('Read the selected instrument and date again before saving.');const p=next.portfolios.find(p=>p.id===recordId);const c=flowlessCandidate;const q={id:id(),symbol:v.symbol,price:c.price,currency:c.currency,date:c.date,origin:'flowless',priceKind:'daily-close',market:'IDX',sourceSymbol:c.symbol,retrievedAt:c.retrievedAt,source:`Flowless local IDX daily summary; ${c.sourceUrl}; retrieved ${c.retrievedAt}`};validateValuation(q,p);(p.valuations??=[]).push(q);}
