function download(body,name){const url=URL.createObjectURL(new Blob([body],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function restore(){dialog.innerHTML=`<form id="restore-form"><div class="dialog-heading"><h2 id="dialog-title">Restore your records</h2><button type="button" class="close" data-action="close" aria-label="Close restore">×</button></div><div class="form-body"><p>Choose a Longhand Office JSON export. We will validate it before you replace your records.</p>${field('Backup file','backup','','file','required accept="application/json,.json"')}<p id="restore-summary"></p><label class="check-label"><input type="checkbox" name="confirm" required> I understand this replaces this active workspace. Export a backup first. Other workspaces are not replaced.</label><p class="form-error" role="alert"></p></div><div class="dialog-footer">${button('Cancel','close','type="button"',true)}<button type="submit" class="primary" disabled>Replace records</button></div></form>`;dialog.showModal();let pending,pendingRuns=[],selection=0,restoreSnapshot=localStorage.getItem(KEY),restoreRevision=storage.revision;const form=$('#restore-form');form.elements.backup.addEventListener('change',async()=>{const ticket=++selection;pending=null;$('#restore-summary').textContent='';form.querySelector('[type=submit]').disabled=true;try{const file=form.elements.backup.files[0];if(!file)return;if(file.size>50000000)throw Error('Backup is too large. Maximum file size is 50 MB.');const bundle=await storage.inspectBackup(JSON.parse(await file.text())),candidate=bundle.records;if(ticket!==selection||!dialog.open||$('#restore-form')!==form)return;pending=candidate;pendingRuns=bundle.analyses;$('#restore-summary').textContent=`Validated: ${pending.portfolios.length} portfolios (${pending.portfolios.filter(p=>portfolioMode(p)==='paper').length} Paper / ${pending.portfolios.filter(p=>portfolioMode(p)==='real').length} Real), ${pending.theses.length} theses, ${pending.decisions.length} decisions.`;$('.form-error').textContent='';form.querySelector('[type=submit]').disabled=false;}catch(e){if(ticket===selection&&dialog.open&&$('#restore-form')===form)form.querySelector('.form-error').textContent=e.message;}});form.addEventListener('submit',async e=>{e.preventDefault();const submit=form.querySelector('[type=submit]');if(submit.disabled)return;submit.disabled=true;try{if(!pending||!form.elements.confirm.checked)return;const restoreCandidate=pending,restoreAnalyses=pendingRuns;form.elements.backup.disabled=true;form.setAttribute('aria-busy','true');if(localStorage.getItem(KEY)!==restoreSnapshot)throw Error('Records changed in another tab. Reopen Restore before replacing them.');if(storage.marker){if(storage.revision!==restoreRevision)throw Error('Vault changed. Reopen Restore.');data=await storage.save(restoreCandidate,'restore',restoreAnalyses);}else{if(pendingRuns.length)throw Error('This backup includes linked analyses. Connect a local vault first so records and analyses can restore atomically.');const serialized=JSON.stringify(restoreCandidate);localStorage.setItem(KEY,serialized);savedSnapshot=serialized;data=restoreCandidate;}storageError='';dialog.close();render();toast('Records restored to this browser.');}catch(e){$('.form-error').textContent='Restore failed: '+e.message;}finally{submit.disabled=false;form.elements.backup.disabled=false;form.removeAttribute('aria-busy');}});}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(['portfolio','thesis','transaction','decision','review','thesis-review','cashflow','valuation','flowless'].includes(a))openForm(a,b.dataset.id,b.dataset.thesis,b.dataset.report);if(a==='close'&&!dialog.querySelector('[aria-busy="true"]'))dialog.close();if(a==='export'){try{download(JSON.stringify(await storage.backup(data),null,2),`longhand-office-${today()}.json`);}catch(e){toast('Export failed: '+e.message);}}if(a==='raw')download(localStorage.getItem(KEY)||'{}',`longhand-office-recovery-${today()}.json`);if(a==='restore')restore();if(a==='refresh'){b.disabled=true;b.textContent='Refreshing…';try{const response=await fetch('https://raw.githubusercontent.com/LonghandResearch/longhandresearch.github.io/main/reports/reports.js',{credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw Error();const text=await response.text();const prefix='window.LONGHAND_REPORTS =';const start=text.indexOf(prefix);if(start<0)throw Error();const reports=JSON.parse(text.slice(start+prefix.length).trim().replace(/;\s*$/,''));if(!Array.isArray(reports)||!reports.every(r=>typeof r.id==='string'&&typeof r.title==='string'&&typeof r.date==='string'&&!Number.isNaN(Date.parse(r.date))))throw Error();catalogue=reports;catalogueCheckedAt=today();render();toast('Published research catalogue refreshed.');}catch{toast('Catalogue unavailable. Your local snapshot is still available.');b.disabled=false;b.textContent='Refresh catalogue';}}});
document.addEventListener('change',e=>{if(e.target.id==='valuation-asof'){if(!e.target.validity.valid||!e.target.value)return;assessmentDates.set(e.target.dataset.portfolio,e.target.value);const p=data.portfolios.find(p=>p.id===e.target.dataset.portfolio);document.querySelector('#manual-valuation').outerHTML=valuationSection(p);document.querySelector('#valuation-asof').focus({preventScroll:true});}});
