function showPurpose(e){const room=(e.type==='pointerover'?document.activeElement?.closest('[data-purpose]'):null)||e.target.closest('[data-purpose]');const hint=$('#room-purpose');if(!hint)return;hint.textContent=room?.dataset.purpose||'Choose a room to explore the office.';const href=room?.querySelector('a')?.getAttribute('href');document.querySelectorAll('.office-room').forEach(r=>r.classList.toggle('lit',!!href&&r.querySelector('a')?.getAttribute('href')===href));}
document.addEventListener('pointerover',showPurpose);
document.addEventListener('focusin',showPurpose);
let navigationTransition;
window.addEventListener('hashchange',()=>{const nextRoute=location.hash.slice(1)||'overview';if(retainResearchLab(nextRoute)){syncWorkspaceShell(nextRoute);mountWorkspaceDestination(nextRoute);return;}const update=()=>{render();if(!recordDestination(nextRoute)){window.scrollTo(0,0);main.focus({preventScroll:true});}};if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches){navigationTransition?.skipTransition();navigationTransition=document.startViewTransition(update);navigationTransition.finished.catch(()=>{});navigationTransition.ready.catch(()=>{});}else update();});
window.addEventListener('storage',e=>{if(e.key===storage.markerKey){location.reload();return;}if(e.key===KEY&&!storage.marker){try{data=e.newValue?validate(JSON.parse(e.newValue)):empty();savedSnapshot=e.newValue;if(dialog.open)dialog.close();render();toast('Records updated in another tab.');}catch{storageError='Another tab saved unreadable records. Existing storage is preserved; reload to recover.';if(dialog.open)dialog.close();render();toast(storageError);}}});
const loaded=await Promise.allSettled([fetch('catalogue.json').then(r=>r.json()),fetch('building.svg').then(r=>r.text())]);if(loaded[0].status==='fulfilled')catalogue=loaded[0].value;if(loaded[1].status==='fulfilled')building=loaded[1].value;if(preview&&savedSnapshot===null&&!storageError&&!storage.marker){try{const sample=validate(await fetch(previewKind==='flowless'?'flowless-example.json':'valuation-example.json').then(r=>r.json()));await persist(sample);if(!location.hash||location.hash==='#overview')location.hash='portfolio/'+sample.portfolios[0].id;}catch{toast('Test example could not be loaded.');}}render();

